from fractions import Fraction

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i + random.randint(0, m - i - 1)
            A[i], A[max_row] = A[max_row], A[i]
            for j in range(i + 1, m):
                factor = Fraction(A[j][i], A[i][i])
                for k in range(n):
                    A[j][k] -= factor * A[i][k]
        return A

    def matrix_multiply(A, B):
        m, n, p = len(A), len(B), len(B[0])
        C = [[Fraction(0) for _ in range(p)] for _ in range(m)]
        for i in range(m):
            for j in range(n):
                for k in range(p):
                    C[i][k] += A[i][j] * B[j][k]
        return C

    def rank_variance(A):
        m, n = len(A), len(A[0])
        U, S, Vt = gaussian_elimination([[Fraction(a) for a in row] for row in A]), [], []
        for i in range(m):
            if U[i][i] != 0:
                S.append(U[i][i])
        return sum((s - sum(S[:i]) / i) ** 2 for i, s in enumerate(S)) / len(S)

    def minimal_representation_length(A):
        m, n = len(A), len(A[0])
        U = gaussian_elimination([[Fraction(a) for a in row] for row in A])
        rank = sum(1 for row in U if any(row[j] != 0 for j in range(n)))
        return rank

    def pearson_correlation(X, Y):
        n = len(X)
        mean_X = sum(X) / n
        mean_Y = sum(Y) / n
        cov = sum((X[i] - mean_X) * (Y[i] - mean_Y) for i in range(n)) / n
        std_X = math.sqrt(sum((X[i] - mean_X) ** 2 for i in range(n)) / n)
        std_Y = math.sqrt(sum((Y[i] - mean_Y) ** 2 for i in range(n)) / n)
        return cov / (std_X * std_Y)

    instances_tested = 0
    rank_variances = []
    representation_lengths = []

    for n in [5, 10, 15, 20, 30, 40]:
